class Solution {
    public List<Integer> lastVisitedIntegers(int[] nums){
        List<Integer> history=new ArrayList<>(),answer=new ArrayList<>();
        int counter=0;
        for(int value:nums)if(value==-1){
            counter++;
            int index=history.size()-counter;
            answer.add(index>=0?history.get(index):-1);
        }else{
            history.add(value);
            counter=0;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun lastVisitedIntegers(nums:IntArray):List<Int>{
        val history=mutableListOf<Int>();
        val answer=mutableListOf<Int>();
        var counter=0;
        for(value in nums)if(value==-1){
            counter++;
            val index=history.size-counter;
            answer.add(if(index>=0)history[index] else -1)
        }else{
            history.add(value);
            counter=0
        };
        return answer
    }
}

